	zip.Describe("PUT /v1/o11y/llm_pricing_rules", zip.Doc{
		Description: "Writes the pricing-rule batch — the single write\nendpoint used by both the user and the Zeus sync job. Per-rule match is by id,\nthen sourceId, then insert; an override row is fully preserved when the\nrequest omits isOverride, only its synced_at stamped.\n\nCallers need the admin role; the runtime's own gate enforces it.",
		Fields: map[string]string{
			"O11yLLMPricingCacheCosts.mode":            "Mode is how cached tokens are counted — subtract (inside input_tokens,\nOpenAI-style), additive (reported separately, Anthropic-style) or unknown.",
			"O11yLLMPricingCacheCosts.read":            "Read is the cost per unit of cache-read tokens.",
			"O11yLLMPricingCacheCosts.write":           "Write is the cost per unit of cache-write tokens.",
			"O11yLLMRulePricing.cache":                 "Cache is the cost of cached tokens, when the model prices them.",
			"O11yLLMRulePricing.input":                 "Input is the cost per unit of input tokens.",
			"O11yLLMRulePricing.output":                "Output is the cost per unit of output tokens.",
			"O11yLLMUpdatablePricingRule.enabled":      "Enabled turns the rule on.",
			"O11yLLMUpdatablePricingRule.id":           "ID matches an existing rule by its id.",
			"O11yLLMUpdatablePricingRule.isOverride":   "IsOverride pins the rule so the sync job skips it. Omit to leave a matched\noverride untouched.",
			"O11yLLMUpdatablePricingRule.modelName":    "Model is the model the rule prices. Required.",
			"O11yLLMUpdatablePricingRule.modelPattern": "ModelPattern are the model-name globs the rule matches. Required.",
			"O11yLLMUpdatablePricingRule.pricing":      "Pricing is the per-unit cost. Required.",
			"O11yLLMUpdatablePricingRule.provider":     "Provider is the model's provider. Required.",
			"O11yLLMUpdatablePricingRule.sourceId":     "SourceID matches an existing rule by its upstream source id.",
			"O11yLLMUpdatablePricingRule.unit":         "Unit is the pricing unit, e.g. per_million_tokens. Required.",
			"O11yLLMUpdatablePricingRules.rules":       "Rules are the rules to create or update, matched per rule.",
		},
	})
